import json
from collections import Counter

with open("mcp-agent-ml-research-read_registry-1778853911265.txt", "r") as f:
    raw = json.load(f)

data = json.loads(raw["result"])
exps = data["data"]["experiments"]

# ========== 1. Active experiments (RUNNING, PREPARING, PENDING, QUEUED, ALLOCATED) ==========
active_statuses = {"RUNNING", "PREPARING", "PENDING", "QUEUED", "ALLOCATED"}
active = []
for eid, e in exps.items():
    if e.get("status") in active_statuses:
        active.append((eid, e))

print("=" * 80)
print("1. ACTIVE EXPERIMENTS (RUNNING / PREPARING / PENDING / QUEUED / ALLOCATED)")
print("=" * 80)
if not active:
    print("  (none)")
else:
    for eid, e in active:
        print(f"\n  exp_id: {eid}")
        print(f"  status: {e.get('status')}")
        print(f"  hypothesis: {e.get('hypothesis', 'N/A')}")
        spec = e.get("spec", {}) or {}
        print(f"  server: {spec.get('server', e.get('server', 'N/A'))}")
        print(f"  gpu: {spec.get('gpu', e.get('gpu', 'N/A'))}")
        print(f"  pid: {spec.get('pid', e.get('pid', 'N/A'))}")
        metrics = e.get("metrics", {}) or {}
        if metrics:
            print(f"  metrics: {json.dumps(metrics, indent=4)}")
        else:
            print(f"  metrics: (none)")

# ========== 2. 5 most recently updated experiments ==========
print("\n" + "=" * 80)
print("2. 5 MOST RECENTLY UPDATED EXPERIMENTS")
print("=" * 80)

sorted_exps = sorted(exps.items(), key=lambda x: x[1].get("updated_at", ""), reverse=True)
for eid, e in sorted_exps[:5]:
    print(f"\n  exp_id: {eid}")
    print(f"  status: {e.get('status')}")
    print(f"  conclusion: {e.get('conclusion', 'N/A')}")
    print(f"  updated_at: {e.get('updated_at', 'N/A')}")
    metrics = e.get("metrics", {}) or {}
    if metrics:
        # Truncate large metrics
        mstr = json.dumps(metrics)
        if len(mstr) > 500:
            print(f"  metrics (truncated): {mstr[:500]}...")
        else:
            print(f"  metrics: {mstr}")
    else:
        print(f"  metrics: (none)")

# ========== 3. Count by status ==========
print("\n" + "=" * 80)
print("3. EXPERIMENT COUNT BY STATUS")
print("=" * 80)

status_counts = Counter(e.get("status", "UNKNOWN") for e in exps.values())
for status, count in sorted(status_counts.items(), key=lambda x: -x[1]):
    print(f"  {status}: {count}")
print(f"  TOTAL: {sum(status_counts.values())}")

# ========== 4. RUNNING experiments - full spec ==========
print("\n" + "=" * 80)
print("4. RUNNING EXPERIMENTS - FULL SPEC")
print("=" * 80)

running = [(eid, e) for eid, e in exps.items() if e.get("status") == "RUNNING"]
if not running:
    print("  (no RUNNING experiments)")
else:
    for eid, e in running:
        print(f"\n  exp_id: {eid}")
        spec = e.get("spec", {}) or {}
        if spec:
            print(f"  spec:")
            for k, v in spec.items():
                vstr = str(v)
                if len(vstr) > 200:
                    vstr = vstr[:200] + "..."
                print(f"    {k}: {vstr}")
        else:
            print(f"  spec: (none)")
        metrics = e.get("metrics", {}) or {}
        if metrics:
            mstr = json.dumps(metrics)
            if len(mstr) > 500:
                print(f"  metrics (truncated): {mstr[:500]}...")
            else:
                print(f"  metrics: {mstr}")

